/**
 * generated by stackra gen from src/config/i18n.config.ts, assets/lang/<locale>/web.json,
 * assets/overrides/leads/<locale>.json and the lang sections of the consumed manifests
 * (marketing: leads; commerce: catalogue; experience) — do not edit
 * Purpose: the complete typed key tree of the public site (its own `web::` namespace plus every
 *          consumed namespace a source or generated file references), the namespace loaders with
 *          overrides applied, `loadMessages` (the root loader) and `translatorFor` (the route
 *          adapters' server-side `t`).
 * Boundary: a leaf is a branded `I18nKey`; a raw string is a type error. Consumed namespaces are
 *           copied by gen into `.stackra/lang/`; gen fails on an `ar` plural missing any of `zero
 *           one two few many other`.
 * Runtime: isomorphic
 */
import { formatMessage, keys, type I18nKey, type Locale } from "@stackra/i18n";

export type { I18nKey };

/** `I18n.<namespace>.<path>`; `_` holds the leaves of a branch that also has children. */
export const I18n = keys({
  web: {
    nav: ["home", "pricing", "store", "contact", "skip", "locale", "main"],
    hero: ["title", "subtitle", "cta", "secondary"],
    features: {
      _: ["title"],
      catalogue: ["title", "body"],
      orders: ["title", "body"],
      loyalty: ["title", "body"],
    },
    pricing: [
      "title",
      "subtitle",
      "interval",
      "month",
      "year",
      "year_hint",
      "per_month",
      "contact_sales",
      "start_trial",
      "trial",
      "highlighted",
    ],
    testimonials: ["title"],
    faq: ["title"],
    cta: ["title", "body", "button"],
    store: ["title", "search", "empty", "more", "out_of_stock", "in_stock"],
    product: ["add_to_cart", "variant_axis", "breadcrumb", "breadcrumb_home"],
    contact: {
      _: [
        "title",
        "subtitle",
        "name",
        "email",
        "company",
        "message",
        "consent",
        "submit",
        "sent",
        "failed",
      ],
      errors: ["name", "email", "message", "consent"],
    },
    consent: ["title", "body", "accept", "decline", "settings", "necessary", "analytics_category"],
    theme: ["toggle", "light", "dark", "system"],
    footer: ["rights", "legal", "privacy", "terms"],
    errors: { not_found: ["title", "body", "home"], server: ["title", "body", "reference"] },
  },
  leads: { refusals: ["rate_limited", "captcha_failed"] },
  catalogue: { refusals: ["variant_unavailable", "variant_not_found", "product_not_found"] },
  experience: { refusals: ["not_found"] },
});

/**
 * Namespace → locale → loader; `leads` has the site's overrides merged key by key
 * (gen/overrides.ts).
 */
export const loaders = {
  web: {
    en: () => import("#assets/lang/en/web.json"),
    ar: () => import("#assets/lang/ar/web.json"),
  },
  leads: {
    en: () => import("../lang/en/leads.json"),
    ar: () => import("../lang/ar/leads.json"),
  },
  catalogue: {
    en: () => import("../lang/en/catalogue.json"),
    ar: () => import("../lang/ar/catalogue.json"),
  },
  experience: {
    en: () => import("../lang/en/experience.json"),
    ar: () => import("../lang/ar/experience.json"),
  },
} as const;

/** Overrides gen merged into the `.stackra/lang` copies, by namespace, locale and key. */
export const overrides = [
  { namespace: "leads", locale: "en", keys: ["refusals.rate_limited", "refusals.captcha_failed"] },
  { namespace: "leads", locale: "ar", keys: ["refusals.rate_limited", "refusals.captcha_failed"] },
] as const;

/** Locales from i18n.config.ts; every namespace above provides each (gen checks). */
export const locales = ["en", "ar"] as const;

/** Loads the catalogues one request needs; `t()` resolves ICU messages from the merged result. */
export async function loadMessages(locale: Locale, names: (keyof typeof loaders)[]) {
  const loaded = await Promise.all(
    names.map(async (name) => [name, (await loaders[name][locale.value]()).default] as const),
 );
  return Object.fromEntries(loaded) as Record<keyof typeof loaders, Record<string, unknown>>;
}

/** A server-side `t()` for one request's locale, used by the route adapters to translate `meta`. */
export async function translatorFor(locale: Locale, names: (keyof typeof loaders)[]) {
  const messages = await loadMessages(locale, names);
  return (key: I18nKey, values?: Record<string, unknown>) =>
    formatMessage(messages, key, values, locale);
}
